const GUPTA_STATS=[{label:"Rulers Featured",value:"5"},{label:"Coin Types",value:"9"},{label:"Time Span",value:"~230 Years"},{label:"Primary Metal",value:"Gold Dinars"}],GUPTA_COINS=[{id:"cg1-archer",ruler:"Chandragupta I",coinType:"King & Queen Type",metal:"Gold",imagery:"Ruler & Queen",script:"Brahmi",period:"c. 319 – 335 CE",circulation:"Magadha, Bihar",symbols:["Standing King","Queen Kumaradevi","Lichchhavi Legend"],obverse:"King Chandragupta I standing on the left facing Queen Kumaradevi on the right, both named in Brahmi legend around the rim.",reverse:"Goddess seated on a lion (Durga/Ambika), with the legend 'Lichchhavayah' referencing the Lichchhavi dynasty of the queen.",history:"This coin type commemorates Chandragupta I's marriage alliance with the Lichchhavi princess Kumaradevi, a union that strengthened Gupta claims over Magadha and is considered the political foundation of the Gupta Empire."},{id:"sg-archer",ruler:"Samudragupta",coinType:"Archer Type",metal:"Gold",imagery:"Standing Archer",script:"Brahmi",period:"c. 335 – 375 CE",circulation:"Gangetic Plains, Central India",symbols:["Bow & Arrow","Garuda Standard","Crescent & Star"],obverse:"King standing facing left, holding a bow in one hand, with a Garuda-topped standard beside him; legend praises him as invincible in battle.",reverse:"Goddess Lakshmi seated on a throne or wicker stool, holding a fillet and cornucopia, legend reads 'Samudragupta'.",history:"The most widely issued Samudragupta type, minted to celebrate his extensive military campaigns recorded in the Allahabad Prashasti, which describe conquests across nearly the entire subcontinent."},{id:"sg-ashvamedha",ruler:"Samudragupta",coinType:"Ashvamedha Type",metal:"Gold",imagery:"Sacrificial Horse",script:"Brahmi",period:"c. 350 – 375 CE",circulation:"Pataliputra Region",symbols:["Yupa (Sacrificial Post)","Horse","Chhatra (Umbrella)"],obverse:"A caparisoned horse standing before a sacrificial post (yupa), commemorating the Ashvamedha (horse sacrifice) performed to proclaim imperial sovereignty.",reverse:"The chief queen standing, holding a fly-whisk, with the legend declaring the king as 'restorer of the Ashvamedha sacrifice'.",history:"Issued specifically to mark Samudragupta's performance of the Ashvamedha ritual, a rare and prestigious ceremony historically reserved for paramount sovereigns, reinforcing his status as chakravartin (universal ruler)."},{id:"sg-lyrist",ruler:"Samudragupta",coinType:"Lyrist (Vina Player) Type",metal:"Gold",imagery:"King Playing Vina",script:"Brahmi",period:"c. 350 – 375 CE",circulation:"Magadha",symbols:["Vina (Lute)","Cushioned Seat"],obverse:"The king seated cross-legged on a high-backed couch, playing a vina (lute-like instrument), reflecting his reputation as a patron of music and the arts.",reverse:"Goddess seated on a wicker stool holding a cornucopia, legend names the king as 'Samudragupta'.",history:"A rare and celebrated type that portrays Samudragupta not as a warrior but as an accomplished musician, an image corroborated by his title 'Kaviraja' (king of poets) found in contemporary inscriptions."},{id:"cg2-couch",ruler:"Chandragupta II",coinType:"Couch (Sofa) Type",metal:"Gold",imagery:"King Reclining",script:"Brahmi",period:"c. 380 – 415 CE",circulation:"Malwa, Gujarat, Gangetic Valley",symbols:["Couch","Chakra (Wheel)"],obverse:"The king shown reclining or seated at ease on an ornate couch, radiating imperial confidence and cultural refinement.",reverse:"Goddess Lakshmi seated on a lotus, legend reads 'Vikramaditya', the title adopted by Chandragupta II after his conquests.",history:"Minted during the Gupta 'Golden Age' under Chandragupta II, whose court hosted the Navaratnas (Nine Gems), including the poet Kalidasa, and whose reign is remembered for prosperity, art, and learning."},{id:"cg2-tiger",ruler:"Chandragupta II",coinType:"Tiger Slayer Type",metal:"Gold",imagery:"King Slaying Tiger",script:"Brahmi",period:"c. 380 – 415 CE",circulation:"Central & Western India",symbols:["Bow","Tiger","Battle Axe"],obverse:"King shown trampling and shooting a tiger with a bow, symbolizing valor and the subjugation of the Shaka Western Kshatrapas.",reverse:"Goddess seated on a lotus (Lakshmi/Ganga), legend proclaims the king a 'tiger among kings'.",history:"Commemorates Chandragupta II's decisive campaigns against the Western Kshatrapas of Gujarat and Malwa, after which he assumed the title 'Vikramaditya' and gained access to western trade ports."},{id:"kg1-horseman",ruler:"Kumaragupta I",coinType:"Horseman Type",metal:"Gold",imagery:"King on Horseback",script:"Brahmi",period:"c. 415 – 455 CE",circulation:"Northern & Central India",symbols:["Horse","Bow","Crescent"],obverse:"The king mounted on a caparisoned horse, bow in hand, commemorating royal military prowess and control of cavalry forces.",reverse:"Goddess Lakshmi seated on a lotus throne holding a lotus stalk, with the legend 'Ajitamahendrah' (the invincible Mahendra).",history:"Reflects the continued military strength of the empire under Kumaragupta I, who also founded Nalanda University, later one of the ancient world's great centres of learning."},{id:"kg1-peacock",ruler:"Kumaragupta I",coinType:"Peacock Type",metal:"Gold",imagery:"King Feeding Peacock",script:"Brahmi",period:"c. 415 – 455 CE",circulation:"Bengal, Bihar",symbols:["Peacock","Karttikeya's Vehicle"],obverse:"The king standing, feeding a peacock (the vahana of Karttikeya, god of war), a personal devotional type unique to Kumaragupta I.",reverse:"Goddess Karttikeyani riding a peacock, legend names the king as devoted to Mahendra (Indra) and Karttikeya.",history:"This unusual type expresses Kumaragupta I's personal devotion to Karttikeya and was struck late in his reign, possibly around the time the empire first faced pressure from Hun incursions in the northwest."},{id:"skg-archer",ruler:"Skandagupta",coinType:"King & Lakshmi Type",metal:"Gold (Debased)",imagery:"Standing King & Goddess",script:"Brahmi",period:"c. 455 – 467 CE",circulation:"Restricted to Core Gupta Territory",symbols:["Bow","Lotus"],obverse:"King standing holding a bow, in the traditional Archer-type pose inherited from Samudragupta, legend proclaims him 'Kramaditya'.",reverse:"Goddess Lakshmi seated on a lotus, holding a lotus flower, facing the legend naming Skandagupta.",history:"Issued during a period of severe strain as the Gupta Empire repelled the first waves of Hephthalite (Hun) invasions; the noticeably reduced gold purity of these coins reflects the mounting economic pressure on the empire."}],GUPTA_REFERENCES=[{text:"Allan, John. Catalogue of the Coins of the Gupta Dynasties. British Museum, 1914.",url:"https://www.britishmuseum.org/collection"},{text:"Altekar, A. S. The Coinage of the Gupta Empire. Numismatic Society of India, 1957.",url:"https://www.numismatics.org.in/"},{text:"American Numismatic Society — Gupta Dynasty Collection Records.",url:"https://numismatics.org/"},{text:"Archaeological Survey of India — Gupta Period Inscriptions & Prashastis.",url:"https://asi.nic.in/"}];